1	import {
2	  COMPONENT_BASE_PREMIUM,
3	  isComponent,
4	  mainItemBasePremium,
5	  type Item,
6	} from "./price-list.js";
7	
8	export type { Item };
9	
10	export interface Customer {
11	  yearsWithMHPCO: number;
12	}
13	
14	const PROCESSING_FEE = 5;
15	
16	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
17	const LOYALTY_DISCOUNT_PERCENT = 20;
18	const LOYALTY_YEARS = 2;
19	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
20	const PERCENT = 100;
21	
22	// Percentages are kept as exact fractions (integer numerator over PERCENT);
23	// scaling by a float rate such as 0.1 yields artefacts like 115.00000000000001.
24	function percentOf(amount: number, percent: number): number {
25	  return (amount * percent) / PERCENT;
26	}
27	
28	/** MHPCO rounds a premium up: every fraction of a G falls to the customer. */
29	function roundInMHPCOsFavor(premium: number): number {
30	  return Math.ceil(premium);
31	}
32	
33	/**
34	 * Settling turns an underwritten amount into the sum actually payable. It is the
35	 * MHPCO's accounting convention, not an underwriting rule: the processing fee is
36	 * charged at the very end, untouched by any percentage modifier, and only the
37	 * settled premium is rounded -- every intermediate amount stays fractional.
38	 */
39	function settlePremium(underwrittenAmount: number): number {
40	  return roundInMHPCOsFavor(underwrittenAmount + PROCESSING_FEE);
41	}
42	
43	const BLOCK_SIZE = 3;
44	const BLOCK_BASE_PREMIUM = 60;
45	
46	/**
47	 * Two items are "alike" when they share an item type -- not merely a family.
48	 * The price list settles this: 2 runes + 1 moonstone form no block (75 G), so
49	 * rune-y and gemstone-y kinship is not enough to build a block together.
50	 */
51	function alikeGroupKey(item: Item): string {
52	  return item.type;
53	}
54	
55	function countAlikeGroups(items: Item[]): Map<string, number> {
56	  const counts = new Map<string, number>();
57	  for (const item of items) {
58	    const key = alikeGroupKey(item);
59	    counts.set(key, (counts.get(key) ?? 0) + 1);
60	  }
61	  return counts;
62	}
63	
64	/**
65	 * A building block of exactly 3 alike components is offered at a special rate;
66	 * the block is not greedy, so 4 or 7 runes form no block at all.
67	 */
68	function componentGroupBasePremium(count: number): number {
69	  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
70	}
71	
72	/**
73	 * The price list quotes a group of alike items as a whole, because only a group
74	 * can qualify for the block rate. Main items have no group rate: they are priced
75	 * one by one.
76	 */
77	function alikeGroupBasePremium(type: string, count: number): number {
78	  return isComponent(type)
79	    ? componentGroupBasePremium(count)
80	    : count * mainItemBasePremium(type);
81	}
82	
83	export function policyBasePremium(items: Item[]): number {
84	  let total = 0;
85	  for (const [type, count] of countAlikeGroups(items)) {
86	    total += alikeGroupBasePremium(type, count);
87	  }
88	  return total;
89	}
90	
91	const CURSE_SURCHARGE_PERCENT = 50;
92	const HIGH_ENCHANTMENT_LEVEL = 5;
93	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
94	
95	/** The threshold is inclusive: exactly enchantment 5 already counts as high. */
96	function isHighlyEnchanted(item: Item): boolean {
97	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
98	}
99	
100	/**
101	 * The risk the price list reads off a single item. The surcharges stack: an
102	 * item that carries several risks is charged for each of them.
103	 */
104	function itemRiskSurchargePercent(item: Item): number {
105	  const cursePercent = item.cursed === true ? CURSE_SURCHARGE_PERCENT : 0;
106	  const enchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
107	  return cursePercent + enchantmentPercent;
108	}
109	
110	/**
111	 * The MHPCO reads risk off main items only. A component is a raw ingredient: it
112	 * bears no curse and no enchantment of its own, and inside a block it has no
113	 * premium of its own that a surcharge could be charged against.
114	 */
115	function bearsOwnRisk(item: Item): boolean {
116	  return !isComponent(item.type);
117	}
118	
119	/**
120	 * An item's own risk surcharges are charged on its price-list row, never on the
121	 * policy total.
122	 */
123	function itemRiskSurcharge(item: Item): number {
124	  if (!bearsOwnRisk(item)) {
125	    return 0;
126	  }
127	  return percentOf(mainItemBasePremium(item.type), itemRiskSurchargePercent(item));
128	}
129	
130	function itemSurcharges(items: Item[]): number {
131	  return items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
132	}
133	
134	/** The threshold is inclusive: exactly 2 years already earns the discount. */
135	function isLongStanding(customer: Customer): boolean {
136	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
137	}
138	
139	/**
140	 * The discount is offered on "each contract after their first", so any contract
141	 * preceded by at least one earlier one qualifies -- the very first does not.
142	 */
143	function isFollowUpContract(previousContracts: number): boolean {
144	  return previousContracts > 0;
145	}
146	
147	/**
148	 * Policy-wide modifiers are all charged against the policy base premium, so the
149	 * MHPCO nets them into a single percentage: a long-standing customer earns a
150	 * loyalty discount, a follow-up contract earns its own discount, and every
151	 * quoted policy carries the first-insurance assessment.
152	 *
153	 * The assessment is deliberately unconditional -- it is not a missing check on
154	 * customer history. The MHPCO treats each item in a quote as a first insurance
155	 * regardless of how long the customer has been with the office, so even a
156	 * long-standing customer's follow-up contract still carries the 10 %.
157	 */
158	function policyWideModifierPercent(customer: Customer, previousContracts: number): number {
159	  const loyaltyPercent = isLongStanding(customer) ? -LOYALTY_DISCOUNT_PERCENT : 0;
160	  const followUpPercent = isFollowUpContract(previousContracts) ? -FOLLOW_UP_DISCOUNT_PERCENT : 0;
161	  return FIRST_INSURANCE_SURCHARGE_PERCENT + loyaltyPercent + followUpPercent;
162	}
163	
164	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
165	  // Item-specific modifiers are charged on the affected item's own base premium;
166	  // policy-wide modifiers are charged on the policy base premium, the plain sum
167	  // of all item base premiums -- never on a base that already carries item
168	  // surcharges. Settling then turns the underwritten amount into the sum payable.
169	  const policyBase = policyBasePremium(items);
170	  const netPolicyModifierPercent = policyWideModifierPercent(customer, previousContracts);
171	  const policyModifiers = percentOf(policyBase, netPolicyModifierPercent);
172	  return settlePremium(policyBase + itemSurcharges(items) + policyModifiers);
173	}
