1	/**
2	 * The MHPCO claim office: it settles a damage report against an open policy. It
3	 * answers what the office pays for a reported damage -- what the damage is worth
4	 * under the policy's clauses, and what the office's settlement conventions then
5	 * deduct from it. It knows nothing about what a policy costs to take out; that
6	 * is the quote's business.
7	 */
8	
9	import { insuranceValue, type Item } from "./price-list.js";
10	
11	export interface Damage {
12	  itemType: string;
13	  amount: number;
14	}
15	
16	export interface Incident {
17	  cause: string;
18	  damages: Damage[];
19	}
20	
21	export interface Policy {
22	  items: Item[];
23	  cap: number;
24	}
25	
26	export interface ClaimResult {
27	  payout: number;
28	}
29	
30	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
31	
32	/**
33	 * The sum a set of items insures for: every item's insurance value, added up.
34	 * This is the underwriting knowledge itself, and it is deliberately stated about
35	 * the items rather than about a policy, because the office must ask it *before*
36	 * a policy exists -- opening one is precisely the act of fixing a cap from it.
37	 */
38	function insuranceSumOf(items: Item[]): number {
39	  return items.reduce((total, item) => total + insuranceValue(item.type), 0);
40	}
41	
42	/** The sum a policy insures, asked of a policy the office has already opened. */
43	export function insuranceSum(policy: Policy): number {
44	  return insuranceSumOf(policy.items);
45	}
46	
47	/**
48	 * Opening a policy fixes the cover it grants: the office caps its total payout at
49	 * twice the insurance sum of the items presented. The cap is fixed from the
50	 * items' own insurance values, so no premium modifier can raise it.
51	 */
52	export function openPolicy(items: Item[]): Policy {
53	  return { items, cap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items) };
54	}
55	
56	const DEDUCTIBLE_PER_DAMAGE = 100;
57	
58	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
59	const HALF_REIMBURSEMENT_PERCENT = 50;
60	const PERCENT = 100;
61	
62	/**
63	 * The claim office's enchantment threshold, deliberately its own rule. The price
64	 * list also reads an enchantment level off an item, but for an unrelated purpose
65	 * and at an unrelated level (>= 5, a premium risk surcharge). The two thresholds
66	 * share no cause: moving one does not move the other, which is why the office
67	 * keeps them apart rather than naming them alike.
68	 */
69	function qualifiesForHalfReimbursement(item: Item): boolean {
70	  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
71	}
72	
73	/**
74	 * What a reported damage is worth under the policy's clauses. A deeply enchanted
75	 * item is reimbursed at half its damage; an item no clause speaks to is
76	 * reimbursed in full.
77	 *
78	 * The office also names a dragon-material clause, and it is deliberately absent
79	 * here rather than overlooked. That clause grants full reimbursement -- which is
80	 * already what an item no clause speaks to receives -- so it can only change an
81	 * outcome by overriding a *reducing* clause. Against the sole reducing clause the
82	 * office has, the half-reimbursement rule, it does not: a dragon-material sword
83	 * at enchantment 8 or 9 is valued at half, not in full. So under every rule the
84	 * office currently holds, a dragon branch would return exactly what this fallback
85	 * returns. Writing it would not encode the clause; it would encode a precedence
86	 * decision between dragon material and some future reducing clause, and the
87	 * office has not made that decision. When a reducing clause appears that dragon
88	 * material is meant to outrank, that precedence becomes observable and belongs
89	 * here then.
90	 */
91	function reimbursementFor(damage: Damage, item: Item): number {
92	  if (qualifiesForHalfReimbursement(item)) {
93	    return (damage.amount * HALF_REIMBURSEMENT_PERCENT) / PERCENT;
94	  }
95	  return damage.amount;
96	}
97	
98	/** The insured item a reported damage refers to, found by its type. */
99	function damagedItem(policy: Policy, damage: Damage): Item {
100	  const item = policy.items.find((insured) => insured.type === damage.itemType);
101	  if (item === undefined) {
102	    throw new Error(`The policy does not cover an item of type "${damage.itemType}"`);
103	  }
104	  return item;
105	}
106	
107	/**
108	 * Settling turns a reimbursement into the sum actually paid. The deductible is
109	 * the MHPCO's settlement convention, not a clause: it is charged per damage
110	 * event, after the reimbursement is valued, and never turns a payout negative.
111	 */
112	function settleReimbursement(reimbursement: number): number {
113	  return Math.max(reimbursement - DEDUCTIBLE_PER_DAMAGE, 0);
114	}
115	
116	/**
117	 * The office's whole decision about one reported damage: find the item it refers
118	 * to, value it under the policy's clauses, then settle that reimbursement. What
119	 * the office then does with several such sums -- adding them up, and one day
120	 * charging them against the policy's remaining cap -- is the claim's business,
121	 * not this one's.
122	 */
123	function settleDamage(policy: Policy, damage: Damage): number {
124	  return settleReimbursement(reimbursementFor(damage, damagedItem(policy, damage)));
125	}
126	
127	export function claim(policy: Policy, incident: Incident): ClaimResult {
128	  const payout = incident.damages.reduce(
129	    (total, damage) => total + settleDamage(policy, damage),
130	    0,
131	  );
132	  return { payout };
133	}
